// Normalize Gmail + Outlook into one format and build the Claude request
const m = $json;
const isOutlook = !!m.from?.emailAddress || m['@odata.etag'] !== undefined;
const strip = s => (s || '')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const email = isOutlook ? {
  source: 'outlook',
  messageId: m.id,
  from: m.from?.emailAddress?.address || '',
  fromName: m.from?.emailAddress?.name || '',
  subject: m.subject || '',
  body: strip(m.body?.content || m.bodyPreview).slice(0, 4000),
} : {
  source: 'gmail',
  messageId: m.id,
  from: m.from?.value?.[0]?.address || m.from?.text || '',
  fromName: m.from?.value?.[0]?.name || '',
  subject: m.subject || '',
  body: (m.text || strip(m.html || m.textAsHtml)).slice(0, 4000),
};

const today = new Date().toISOString().slice(0, 10);
const system = `You classify emails for an IT consultant in the Netherlands. Today is ${today}.
Reply with ONLY a JSON object, no other text:
{"category":"payment_due|important|promo|spam","amount":"string or null","due_date":"YYYY-MM-DD or null","suspicious":true|false,"confidence":0.0-1.0,"reason":"max 15 words"}

Rules:
- Job and assignment matches are ALWAYS important, never promo: vacancy or assignment notifications (e.g. freelance.nl "Nieuwe match", opdrachtmatches), LinkedIn job alerts and job offers, and any mail from recruiters or staffing/intermediary agencies about a role or assignment. This rule overrides the promo rule, even when the mail is automated.
- payment_due: a real invoice, bill, payment request, reminder (aanmaning) or direct debit notice (incasso) that the user must pay. Extract amount and due date if present.
- Receipts or confirmations of payments already made are NOT payment_due (use important or promo).
- important: personal or business mail that needs attention, no payment.
- promo: newsletters, marketing, ads, offers, automated notifications without action (except job/assignment matches, see above).
- spam: unsolicited junk or scams.
- suspicious: true when a payment request looks like phishing: sender domain does not match the company named, urgent pressure, unusual payment method, payment only via a link, or an unexpected invoice.`;

email.requestBody = {
  model: 'claude-haiku-5-5',
  max_tokens: 400,
  system,
  messages: [{
    role: 'user',
    content: `From: ${email.fromName} <${email.from}>\nSubject: ${email.subject}\n\n${email.body}`,
  }],
};

return { json: email };

// Parse Claude's answer and decide the label
const CONFIG = {
  MIN_CONFIDENCE: 0.7,     // below this -> "Te checken"
  REMIND_DAYS_BEFORE: 2,   // calendar reminder X days before due date
};
const LABELS = {
  payment_due: 'Te betalen',
  promo: 'Reclame',
  spam: 'AI-Spam',
  check: 'Te checken',
  important: null,         // stays in inbox, no label
};

const email = $('Normalize + prompt').item.json;
let ai = {};
try {
  const text = ($json.content || []).filter(c => c.type === 'text').map(c => c.text).join('');
  ai = JSON.parse(text.replace(/```json|```/g, '').trim());
} catch (e) {
  ai = { category: 'check', confidence: 0, reason: 'AI response could not be parsed' };
}

let category = ai.category || 'check';
if (ai.suspicious === true || Number(ai.confidence ?? 0) < CONFIG.MIN_CONFIDENCE) category = 'check';

let remindDate = null;
if (category === 'payment_due' && /^\d{4}-\d{2}-\d{2}$/.test(ai.due_date || '')) {
  const d = new Date(ai.due_date + 'T09:00:00');
  d.setDate(d.getDate() - CONFIG.REMIND_DAYS_BEFORE);
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  tomorrow.setHours(9, 0, 0, 0);
  remindDate = (d < new Date() ? tomorrow : d).toISOString();
}

const { requestBody, ...rest } = email;
return {
  json: {
    ...rest,
    category,
    label: LABELS[category] ?? null,
    amount: ai.amount ?? null,
    due_date: ai.due_date ?? null,
    suspicious: !!ai.suspicious,
    confidence: ai.confidence ?? 0,
    reason: ai.reason || '',
    remindDate,
  },
};

// Map label names to Gmail label IDs
const labels = $input.first().json.labels || [];
const byName = Object.fromEntries(labels.map(l => [l.name.toLowerCase(), l.id]));

return $('Gmail items').all().map(i => {
  const id = byName[i.json.label.toLowerCase()];
  if (!id) throw new Error(`Gmail label "${i.json.label}" not found. Create it in Gmail first.`);
  const addLabelIds = [id];
  if (i.json.category === 'payment_due') addLabelIds.push('STARRED');
  return { json: { ...i.json, addLabelIds } };
});

// Only payments with a due date -> calendar reminder
return $input.all()
  .filter(i => i.json.category === 'payment_due' && i.json.remindDate)
  .map(i => {
    const start = new Date(i.json.remindDate);
    const end = new Date(start.getTime() + 30 * 60000);
    return {
      json: {
        ...i.json,
        calendarEvent: {
          summary: `💶 Betalen: ${i.json.subject}`,
          description: `Bedrag: ${i.json.amount ?? 'onbekend'}\nVervaldatum: ${i.json.due_date}\nVan: ${i.json.from}\nMailbox: ${i.json.source}`,
          start: { dateTime: start.toISOString() },
          end: { dateTime: end.toISOString() },
          reminders: { useDefault: true },
        },
      },
    };
  });
